using System.Linq;

// AuroraRevit v1.8.3 educational template: Find Rooms Missing Department
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_Rooms);
    var rooms = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).WhereElementIsNotElementType().ToElements();
    var missing = rooms.Count(room => string.IsNullOrWhiteSpace(room.LookupParameter("Department")?.AsString()));
}

using System;
using Autodesk.Revit.DB;
using System.Linq;

// AuroraRevit v1.8.3 educational template: Create a Reflected Ceiling Plan
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_Ceilings);
    var level = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().FirstOrDefault(x => x.Name == "Level 1");
    if (level == null) return;
    var view = ViewPlan.Create(doc, new ElementId(BuiltInViewFamily.ViewFamilyCeilingPlan), level.Id);
    view.Name = "RCP - Level 1";
}

using System;
