using System.Linq;

// AuroraRevit v1.8.3 educational template: Count Windows by Type
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_Windows);
    var windows = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Windows).WhereElementIsNotElementType().ToElements();
    var counts = windows.GroupBy(x => x.GetTypeId()).Select(g => new { TypeId = g.Key, Count = g.Count() }).ToList();
}

