// AuroraRevit v1.8.3 educational template: Create a Presentation Sheet
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_Sheets);
    var titleBlock = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_TitleBlocks).WhereElementIsElementType().FirstOrDefault();
    if (titleBlock == null) return;
    var sheet = ViewSheet.Create(doc, titleBlock.Id);
    sheet.SheetNumber = "A-100";
    sheet.Name = "Presentation";
}
